defmodule Ledger.Money do
  @moduledoc """
  An exact-integer money value with currency and minor-unit amount.
  """

  @enforce_keys [:currency, :amount]
  defstruct [:currency, :amount]

  @typedoc "Supported currency atom."
  @type t :: %__MODULE__{currency: atom(), amount: integer()}

  # Maps supported currency atom → exponent.
  @exponents %{bhd: 3, eur: 2, jpy: 0, usd: 2}

  @currencies ~w[bhd eur jpy usd]a

  @doc "Supported currencies in order."
  def currencies, do: @currencies

  @doc "Exponent for the given currency."
  def exponent(currency) when is_atom(currency) do
    case Map.fetch(@exponents, currency) do
      {:ok, e} -> e
      :error -> raise ArgumentError, "unknown currency #{inspect(currency)}"
    end
  end

  @doc "Create money from integer amount and currency."
  def new(amount, currency) when is_integer(amount) and is_atom(currency) do
    if Map.has_key?(@exponents, currency) do
      {:ok, %__MODULE__{amount: amount, currency: currency}}
    else
      {:error, :unknown_currency}
    end
  end

  def new(amount, currency) when not is_integer(amount) do
    {:error, :invalid_amount}
  end

  def new(_amount, _currency), do: {:error, :unknown_currency}

  @doc "Create money or raise ArgumentError."
  def new!(amount, currency) do
    case new(amount, currency) do
      {:ok, money} -> money
      {:error, reason} -> raise ArgumentError, "#{reason} building money"
    end
  end

  @doc "Money of zero amount in the given currency."
  def zero(currency) when is_atom(currency) do
    %__MODULE__{amount: 0, currency: currency}
  end

  @doc "Sum two money values; errors on currency mismatch."
  def add(%__MODULE__{currency: c, amount: a}, %__MODULE__{currency: c, amount: b}) do
    {:ok, %__MODULE__{amount: a + b, currency: c}}
  end

  def add(%__MODULE__{}, %__MODULE__{}), do: {:error, :currency_mismatch}

  @doc "Subtract two money values; errors on currency mismatch."
  def subtract(%__MODULE__{currency: c, amount: a}, %__MODULE__{currency: c, amount: b}) do
    {:ok, %__MODULE__{amount: a - b, currency: c}}
  end

  def subtract(%__MODULE__{}, %__MODULE__{}), do: {:error, :currency_mismatch}

  @doc "Multiply money by an integer factor."
  def multiply(%__MODULE__{amount: amount, currency: currency}, factor) when is_integer(factor) do
    {:ok, %__MODULE__{amount: amount * factor, currency: currency}}
  end

  def multiply(%__MODULE__{}, _), do: {:error, :invalid_factor}

  @doc "Sum a list of money values in the given currency; empty lists become zero."
  def sum(list, currency) when is_list(list) and is_atom(currency) do
    Enum.reduce_while(list, {:ok, zero(currency)}, fn
      %__MODULE__{currency: ^currency, amount: amount}, {:ok, acc} ->
        {:cont, {:ok, %__MODULE__{currency: currency, amount: acc.amount + amount}}}

      %__MODULE__{currency: _}, _acc ->
        {:halt, {:error, :currency_mismatch}}
    end)
  end

  @doc "Compare two money values."
  def compare(%__MODULE__{currency: c, amount: a}, %__MODULE__{currency: c, amount: b}) do
    case {a < b, a > b} do
      {true, _} -> :lt
      {_, true} -> :gt
      {_ , _} -> :eq
    end
  end

  def compare(%__MODULE__{}, %__MODULE__{}),
    do: raise(ArgumentError, "cannot compare money in different currencies")

  @doc "Canonical string: uppercase code, space, major units with exponent fraction digits."
  def to_string(%__MODULE__{amount: amount, currency: currency}) do
    exponent = Map.fetch!(@exponents, currency)
    code = currency |> Atom.to_string() |> String.upcase()
    abs_amount = abs(amount)

    str =
      if exponent == 0 do
        Integer.to_string(abs_amount)
      else
        digits = Integer.to_string(abs_amount)
        # Pad with leading zeros to at least exponent + 1 digits so we can split.
        padded = String.pad_leading(digits, exponent + 1, "0")
        {int, frac} = String.split_at(padded, -exponent)
        int <> "." <> frac
      end

    if amount < 0, do: "#{code} -#{str}", else: "#{code} #{str}"
  end
end

